### **Problem Type 2: Linked List Traversal & Manipulation**

**Description**: Given a linked list, perform operations like reversal, cycle detection, or finding middle node.

**Example**: *Reverse a Linked List*

```cpp
#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
    Node(int x) : data(x), next(nullptr) {}
};

Node* reverseList(Node* head) {
    Node* prev = nullptr;
    Node* curr = head;

    while (curr) {
        Node* nextTemp = curr->next;  // Save next node
        curr->next = prev;             // Reverse the link
        prev = curr;                   // Move prev forward
        curr = nextTemp;               // Move curr forward
    }

    return prev;  // New head
}

void printList(Node* head) {
    while (head) {
        cout << head->data << " -> ";
        head = head->next;
    }
    cout << "null\n";
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);

    cout << "Original: ";
    printList(head);

    head = reverseList(head);
    cout << "Reversed: ";
    printList(head);

    return 0;
}
```

